743:             checked_blob_limit(stderr, &record.intent.output_dir, bounds.stderr_bytes)?;
744:         }
745:         if report.schema != "tl3.runner_report.v1"
746:             || report.run != binding.id
747:             || report.request_digest != record.intent.request_digest
748:             || report.tree != record.request.tree
749:             || report.runner_digest != record.request.runner.executable_digest
750:             || report.runtime_digest != record.request.runtime.manifest_digest
751:             || report.suite != record.request.suite
752:             || report.cases.len() > 100_000
753:         {
754:             return Ok(false);
755:         }
756:         if report.cleanup_complete {
757:             if let Some(cleanup) = &report.cleanup
758:                 && !cleanup_stopped(record, &binding.id, cleanup)?
759:             {
760:                 return Ok(false);
761:             }
762:             if !super::cleanup::all_stopped(record) {
763:                 return Ok(false);
764:             }
765:         }
766:         if matches!(report.outcome, ReportOutcome::RefusedBeforeTests) {
767:             return Ok(report.tests_started == 0 && report.cases.is_empty());
768:         }
769:         if report.outcome == ReportOutcome::PostBeginLaunchFailure {
770:             return Ok(!report.complete
771:                 && !report.cleanup_complete
772:                 && report.tests_started == 0
773:                 && report.cases.is_empty()
774:                 && report.runtime_binding.is_none()
775:                 && report.runtime_bindings.is_empty()
776:                 && super::launch_failure::candidate(record, &report.launch_failures)?);
777:         }
778:         if matches!(
779:             record.request.runtime.runtime,
780:             ExecutionRuntime::RootlessPodman { .. }
781:         ) {
782:             let facts: Vec<_> = report
783:                 .runtime_binding
784:                 .iter()
785:                 .chain(report.runtime_bindings.iter())
786:                 .collect();
787:             let containers: Vec<_> = record
788:                 .runtime_ownerships
789:                 .iter()
790:                 .filter(|owned| owned.container.is_some())
791:                 .collect();
792:             let mut observed = BTreeSet::new();
