803:             }
804:         }
805:         if matches!(report.outcome, ReportOutcome::EnvironmentLost) {
806:             return Ok(true);
807:         }
808:         if !report.complete {
809:             return Ok(false);
810:         }
811:         match &record.request.suite {
812:             Suite::WorkerTests { .. } | Suite::Generator { .. } => {
813:                 super::worker_protocol::report_identity(record, report)
