177: pub(super) fn all_stopped(record: &Record) -> bool {
178:     let executions = executions(record);
179:     if executions.is_empty() {
180:         // InJob Podman cannot be invoked without a durable launch intent. Native
181:         // clean stops the wrapper; OwnScope absence remains insufficient.
182:         return !record.dispatched
183:             || (matches!(
184:                 record.request.runtime.runtime,
185:                 ExecutionRuntime::RootlessPodman {
186:                     mode: ContainerMode::InJob,
187:                     ..
188:                 }
189:             ) && record
190:                 .events
191:                 .iter()
192:                 .any(|event| matches!(event.fact, NativeFact::Clean)));
193:     }
194:     executions.iter().all(|owned| {
195:         record
196:             .cleanup_evidence
197:             .get(&owned.execution)
198:             .is_some_and(|reference| stopped(record, &owned.run, reference).unwrap_or(false))
199:     })

