91: pub fn judge(input: Input) -> Decision {
92:     let pre_existing = matches!(input.kind, Kind::Regression)
93:         && matches!(input.base, Outcome::Assertion | Outcome::Error);
94:     let infrastructure = matches!(input.base, Outcome::NoReport)
95:         || matches!(input.head, Outcome::NoReport)
96:         || matches!(input.forced, Some(Outcome::NoReport));
97:     let candidate = match input.kind {
98:         Kind::Demonstrating if input.forced.is_some() => {
99:             matches!(input.base, Outcome::Assertion)
100:                 && matches!(input.head, Outcome::Passed)
101:                 && matches!(input.forced, Some(Outcome::Passed))
102:         }
103:         Kind::Demonstrating | Kind::Reproducing => {
104:             matches!(input.base, Outcome::Assertion | Outcome::AddedName)
105:                 && matches!(input.head, Outcome::Passed)
106:         }
107:         Kind::Regression => {
108:             let available = !matches!(
109:                 input.base,
110:                 Outcome::Skipped | Outcome::Missing | Outcome::Uncollected | Outcome::NoReport
111:             );
112:             available
113:                 && (matches!(input.head, Outcome::Passed)
114:                     || pre_existing && matches!(input.head, Outcome::Assertion | Outcome::Error))
115:         }
116:         Kind::BehaviorPreserving => {
117:             matches!(input.base, Outcome::Passed) && matches!(input.head, Outcome::Passed)
118:         }
119:     };
120:     let reason_ok = !matches!(input.base, Outcome::Assertion)
121:         || !matches!(input.kind, Kind::Demonstrating | Kind::Reproducing)
122:         || matches!(input.reason, Reason::Matched | Reason::DeclaredSymptom);
123:     Decision {
124:         passed: candidate && reason_ok,
125:         pre_existing,
126:         infrastructure,
127:     }
